<?php
require_once __DIR__.'/migrated_history.php';
require_once __DIR__.'/history_class_filter.php';
require_once __DIR__.'/history_operator_filter.php';
/** Legacy receipts are evidence, not newly issued DU bills. */
function mh_registration_render(mysqli $db): void {
    $classes=history_class_filter($db,$_GET);$options=history_operator_options($db);
    $operators=history_operator_choices($_GET['operator']??null,$options);
    $size=page_size_param('per_page',[10,25,50],25);
    $input=array_replace($_GET,['search'=>(string)($_GET['q']??''),'all_periods'=>'1','du_only'=>'1']);
    $result=mh_payment_page($db,$input,$classes,$operators,'','',page_int_param('page'),$size);
    $receipts=mh_receipts_many($db,$result['rows']);
    filter_output_start();
    ?><!doctype html><html lang="id" data-palette="<?= unit_palette_for_view() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histori Daftar Ulang Legacy | SistemSPP</title>
    <?php foreach(['style','payment_history','payment_details','legacy_workspace'] as $css): ?><link rel="stylesheet" href="../assets/css/<?= $css ?>.css?v=<?= filemtime(__DIR__.'/../assets/css/'.$css.'.css') ?>"><?php endforeach; ?>
    <script>document.documentElement.dataset.theme=localStorage.getItem('spp_theme')||'light';</script></head><body><div class="layout"><?php include __DIR__.'/sidebar.php'; ?><main class="main-content"><div class="topbar"><button class="sidebar-toggle" onclick="toggleSidebar()" aria-label="Buka menu">☰</button><div class="topbar-title"><h2>Riwayat Daftar Ulang</h2><span class="breadcrumb">SistemSPP / Pembayaran / Histori Legacy</span></div></div>
    <div class="ph-page-content"><header class="ph-hero"><div class="ph-hero-copy"><span class="ph-hero-icon"><?= authorization_icon('history') ?></span><div><h1>Histori Daftar Ulang Legacy</h1><p>Pembayaran sumber asli. Nominal histori tidak menentukan status lunas tagihan operasional.</p></div></div><nav class="ph-tabs" aria-label="Jenis riwayat"><a href="riwayat_daftar_ulang.php">Riwayat Aktif</a><a href="riwayat_daftar_ulang.php?view=deleted">Riwayat Dihapus</a><a href="riwayat_daftar_ulang.php?view=legacy" aria-current="page">Histori Legacy</a></nav></header>
    <section class="ph-filter-card"><form method="get" class="ph-filter-form"><input type="hidden" name="view" value="legacy"><div class="field-row"><label class="field-label" for="legacy-du-search">Nama / identitas sumber</label><input class="field-input" id="legacy-du-search" name="q" value="<?= authorization_escape($_GET['q']??'') ?>"></div><?php history_class_field($classes,'legacy-du-class');history_operator_field($options,'legacy-du-operator'); ?><div class="ph-filter-actions"><button class="btn btn-primary">Cari</button><a class="btn btn-ghost" href="riwayat_daftar_ulang.php?view=legacy">Reset</a></div></form></section>
    <section class="ph-list-panel"><header class="ph-panel-heading"><div><h3><?= number_format($result['total'],0,',','.') ?> transaksi Legacy</h3><p>Tanggal atau tahun ajaran yang kosong tetap ditampilkan sebagai tidak tercatat.</p></div></header><div class="ph-record-list">
    <?php foreach($result['rows'] as $p):$receipt=$receipts[(int)$p['id']]; ?><article class="ph-record-card"><div class="ph-record"><div class="ph-record-identity"><strong><?= authorization_escape($p['NAMA']) ?></strong><span><?= authorization_escape($p['NO_INDUK']) ?></span><small><?= $p['owner_type']==='account'?'Pemilik rekening non-siswa':'Siswa' ?></small></div><span><?= authorization_escape($receipt['source_period']?:'Tahun ajaran tidak tercatat') ?></span><span><?= $p['TGL_BYR']?authorization_escape(spp_date_label($p['TGL_BYR'])):'Tanggal tidak tercatat' ?></span><strong><?= payment_history_money($p['total_jumlah']) ?></strong><a class="btn btn-ghost" href="lihat.php?<?= authorization_escape(http_build_query(['all_periods'=>'1','selected'=>$p['id'],'selected_unit'=>$p['unit_id'],'back_context'=>mh_return_create('pembayaran/riwayat_daftar_ulang.php',array_replace($_GET,['view'=>'legacy','page'=>$result['page']]),(int)$p['unit_id'],'receipt',(int)$p['id'])])) ?>">Rincian pembayaran</a></div></article><?php endforeach; ?>
    <?php if(!$result['rows']): ?><p class="ph-empty">Tidak ada histori Daftar Ulang Legacy sesuai filter.</p><?php endif; ?></div><?php render_pagination('riwayat_daftar_ulang.php',$_GET+['view'=>'legacy'],$result['page'],$result['pages'],$result['total'],$size,'transaksi'); ?></section></div></main></div><script src="../assets/js/date_format.js?v=<?= filemtime(__DIR__.'/../assets/js/date_format.js') ?>"></script><script src="../assets/js/app.js"></script></body></html><?php
}
